/* ===== MINI-GAME: Steady the Flame (first-contact-hope) ===== */
const MG_INSTRUCTOR_LINE = "You hold the flame steady, and those who approach without flinching will kneel.";
const MG = {
  active: false,
  shown_tip: false,
  nomads: [],
  flame: 50,
  holding: false,
  time: 0,
  won: false,
  failed: false,
  exit_timer: 0
};
function mgInit(st = MG) {
  st.active = false;
  st.shown_tip = false;
  st.nomads = [];
  st.flame = 50;
  st.holding = false;
  st.time = 0;
  st.won = false;
  st.failed = false;
  st.exit_timer = 0;
}
function mgSpawnRing(st = MG) {
  const ring = [];
  const count = 8;
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const dist = 180 + Math.random() * 40;
    ring.push({
      x: Math.cos(angle) * dist,
      y: Math.sin(angle) * dist,
      speed: 0.3 + Math.random() * 0.2,
      state: 'approach',
      recoil: 0
    });
  }
  st.nomads = ring;
}
function mgStep(st = MG, holding = false) {
  st.holding = holding;
  st.time++;
  if (holding) st.flame = Math.min(100, st.flame + 1.2);
  else st.flame = Math.max(0, st.flame - 0.8);
  const pulse = Math.sin(st.time * 0.08) * 3;
  const effective = st.flame + pulse;
  let approaching = 0;
  for (const n of st.nomads) {
    if (n.state === 'gone') continue;
    const dist = Math.sqrt(n.x * n.x + n.y * n.y);
    if (n.state === 'approach') {
      let ok = effective >= 40 && effective <= 65;
      if (ok) {
        n.recoil = Math.max(0, n.recoil - 0.05);
        const dx = -n.x / dist, dy = -n.y / dist;
        n.x += dx * n.speed;
        n.y += dy * n.speed;
        if (dist < 20) return { win: true, st };
        approaching++;
      } else {
        n.recoil = Math.min(1, n.recoil + 0.1);
        if (n.recoil > 0.6) {
          n.state = 'gone';
        } else {
          const side = Math.random() < 0.5 ? 1 : -1;
          n.x += side * 0.3;
          n.y += side * 0.3;
        }
      }
    }
  }
  if (approaching === 0 && st.nomads.every(n => n.state === 'gone')) return { fail: true, st };
  return { st };
}

