// MG: Steady the Flame — trigger, lifecycle, draw
if (location.hash.includes('mg') && phase === 'play' && !transitioning && !MG.active && SIM.sleep_no === 0) {
  mgInit();
  MG.active = true;
  mgSpawnRing();
}
if (!MG.active && phase === 'play' && !transitioning && SIM.sleep_no >= 1) {
  const grey = SIM.npcs.filter(x => x.tribe === -1 && !x.burn);
  if (grey.length >= 5) {
    let near = 0;
    for (const x of grey) if (cheb(x.pos, SIM.player_pos) <= 8) near++;
    if (near >= 5) {
      mgInit();
      MG.active = true;
      mgSpawnRing();
    }
  }
}
if (MG.active) {
  if (!MG.shown_tip) {
    setTip(MG_INSTRUCTOR_LINE);
    MG.shown_tip = true;
  }
  if (!MG.won && !MG.failed) {
    const holding = this.input.keyboard.addKey('SPACE').isDown;
    const res = mgStep(MG, holding);
    if (res.win) { MG.won = true; MG.exit_timer = 90; }
    if (res.fail) { MG.failed = true; MG.exit_timer = 60; }
  }
  const ox = this.overlay, px = SIM.player_pos[0] * CELL + CELL / 2, py = SIM.player_pos[1] * CELL + CELL / 2;
  ox.fillStyle(0x000000, 0.4);
  ox.fillRect(0, 0, VIEW, VIEW);
  const fr = (MG.flame / 100) * 50 + 20;
  const fa = 0.3 + (MG.flame / 100) * 0.5;
  const fc = MG.flame < 40 ? 0xaaaaaa : MG.flame > 65 ? 0xffffff : 0xffdd88;
  ox.fillStyle(fc, fa);
  ox.fillCircle(px, py, fr);
  ox.fillStyle(0xffeecc, 0.8);
  ox.fillCircle(px, py, 6);
  for (const n of MG.nomads) {
    if (n.state === 'gone') continue;
    const nx = px + n.x, ny = py + n.y;
    const lean = n.recoil < 0.3 ? 1 : 0;
    ox.fillStyle(lean ? 0x88cc88 : 0xcc8888, 0.7);
    ox.fillCircle(nx, ny, 8);
    if (n.recoil > 0.3) {
      ox.lineStyle(2, 0xffffff, 0.6);
      ox.strokeCircle(nx - 4, ny - 4, 3);
    }
  }
  if (MG.won || MG.failed) {
    MG.exit_timer--;
    if (MG.won) {
      const conv = MG.nomads.filter(n => n.state === 'approach').slice(0, 3);
      for (const c of conv) {
        const nx = px + c.x, ny = py + c.y;
        ox.fillStyle(0xffdd00, 0.9);
        ox.fillCircle(nx, ny, 10);
      }
      if (MG.exit_timer === 85) {
        let added = 0;
        for (const x of SIM.npcs) {
          if (x.tribe === -1 && !x.burn && cheb(x.pos, SIM.player_pos) <= 8 && added < 3) {
            x.tribe = -1;
            x.v = 10;
            x.ever_nonzero = true;
            added++;
          }
        }
      }
    }
    if (MG.exit_timer <= 0) {
      mgInit();
    }
  }
}

