// M1: mgStep flame rises when holding, falls when released
{ const s = { flame: 50, holding: false, time: 0, nomads: [], won: false, failed: false };
  mgStep(s, true); const r1 = s.flame > 50;
  s.flame = 50; mgStep(s, false); const r2 = s.flame < 50;
  out.push(['M1 flame rises held, falls released', r1 && r2, `held=${r1} released=${r2}`]); }
// M2: nomads approach when flame in band, drift when out
{ const s = { flame: 52, holding: false, time: 0, nomads: [{ x: 100, y: 0, speed: 0.4, state: 'approach', recoil: 0 }], won: false, failed: false };
  const d0 = Math.sqrt(s.nomads[0].x ** 2 + s.nomads[0].y ** 2);
  mgStep(s, false);
  const d1 = Math.sqrt(s.nomads[0].x ** 2 + s.nomads[0].y ** 2);
  const approached = d1 < d0;
  out.push(['M2 nomad approaches when flame steady', approached, `${d0.toFixed(1)}->${d1.toFixed(1)}`]); }
